&lt;p data-renderer-start-pos=&quot;4851&quot; data-local-id=&quot;7b1fc9cd775f&quot;&gt;First-author publications in NeurIPS, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;ICML&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;ICLR&lt;/span&gt;, MLSys, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;ACL&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;EMNLP&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;ASPLOS&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;OSDI&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;SOSP&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;ISCA&lt;/span&gt;, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;HPCA&lt;/span&gt;, or comparable venues.&lt;/p&gt;
